// Payload from 511: { messages, messageCount, latest }
let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) { return null; }
}
const latest = (payload && payload.latest) || null;
if (!latest || latest.from == null || latest.from === '' || typeof latest.text !== 'string') {
    return null;
}

const from = String(latest.from).trim();
let rawText = (latest.text || '').trim();
if (!rawText) return null;

const lines = rawText.split(/[\r\n]+/).map(s => s.trim()).filter(s => s.length > 0);
const commandLine = lines.find(l => !/^\+[A-Z]/.test(l) && !l.startsWith('AT')) || lines[lines.length - 1] || rawText;
rawText = commandLine;

const digitsFrom = from.replace(/\D/g, '');
const replyTo = digitsFrom.length > 0 ? digitsFrom : from;

const allowedPhones = flow.get('sms_allowed_phones');
if (Array.isArray(allowedPhones) && allowedPhones.length > 0) {
    const allowed = allowedPhones.some(p => {
        const normP = String(p).replace(/\D/g, '');
        if (!normP) return false;
        if (digitsFrom === normP) return true;
        const longer = digitsFrom.length >= normP.length ? digitsFrom : normP;
        const shorter = digitsFrom.length < normP.length ? digitsFrom : normP;
        return longer.endsWith(shorter) || shorter.endsWith(longer);
    });
    if (!allowed) {
        node.warn('SMS from unauthorized number: ' + from + ' (digits: ' + digitsFrom + ')');
        return null;
    }
}

const KNOWN = new Set([
    'help','commands','list','start',
    'boot','shutdown','stop','force','force_shutdown','status','state',
    'gate','gate_open','gate_status',
    'sliding_open','sliding_close','sliding_trigger','sliding_status',
    'secondary_open','secondary_close','secondary_trigger','secondary_stop',
    'secondary_light_left','secondary_light_right','secondary_status',
    'garden_on','garden_off','garden_toggle','garden_status',
    'lights_on','lights_off','lights_status','light',
    'illum','illum_status',
    'irrig','irrig_status',
    'irrig_a_start','irrig_a_pause','irrig_a_resume','irrig_a_skip',
    'irrig_b_start','irrig_b_pause','irrig_b_resume','irrig_b_skip',
    'pump_start','pump_stop','pump_drain','pump_status',
    'pump_trench1_on','pump_trench1_off','pump_trench2_on','pump_trench2_off',
    'aquarium_on','aquarium_off','aquarium_toggle','aquarium_status',
    'camera_status','camera_help',
    'sms_status','sms_log',
    'energy_status','energy_start','energy_stop',
    'huawei_status',
    'scala1_status','scala1_start','scala1_stop',
    'consumer','consumer_status'
]);

const tokens = rawText
    .replace(/^\//, '')
    .replace(/_/g, ' ')
    .split(/\s+/)
    .map(s => s.trim().toLowerCase())
    .filter(s => s.length > 0);

if (tokens.length === 0) return null;

let command = tokens[0];
let args = tokens.slice(1);
for (let n = Math.min(tokens.length, 4); n >= 2; n--) {
    const cand = tokens.slice(0, n).join('_');
    if (KNOWN.has(cand)) {
        command = cand;
        args = tokens.slice(n);
        break;
    }
}

msg.sms = {
    from: replyTo,
    command: command,
    args: args,
    originalText: rawText
};
msg.payload = latest;
return msg;

const cmd = msg.sms.command;
const args = msg.sms.args || [];
const to = msg.sms.from;

function replyParts(texts) {
    const parts = (Array.isArray(texts) ? texts : [texts])
        .map(t => String(t || '').substring(0, 150))
        .filter(t => t.length > 0);
    if (!parts.length) parts.push('No content.');
    return parts.map(text => ({
        payload: JSON.stringify({ to: to, text: text }),
        topic: 'sms/gateway/command/send'
    }));
}

if (cmd === 'help' || cmd === 'commands' || cmd === 'list' || cmd === 'start') {
    const domain = (args[0] || '').toLowerCase();
    const domainHelp = {
        server: 'SERVER: BOOT|SHUTDOWN|FORCE [dell|hp|media]. STATUS.',
        gate: 'GATE: GATE_OPEN, GATE_STATUS. SLIDING_OPEN|CLOSE|TRIGGER|STATUS. SECONDARY_OPEN|CLOSE|TRIGGER|STOP|LIGHT_LEFT|LIGHT_RIGHT|STATUS.',
        garden: 'GARDEN: GARDEN_ON|OFF|TOGGLE|STATUS.',
        lights: 'LIGHTS: LIGHTS_ON|OFF|STATUS. LIGHT <1-16> ON|OFF.',
        illum: 'ILLUM: ILLUM <1-4> ON|OFF. ILLUM OFF (all). ILLUM_STATUS.',
        irrig: 'IRRIG: IRRIG <1-12> ON|OFF. IRRIG_STATUS. IRRIG_A|B_START|PAUSE|RESUME|SKIP.',
        pump: 'PUMP: PUMP_START|STOP|DRAIN|STATUS. PUMP_TRENCH1|2_ON|OFF.',
        aquarium: 'AQUARIUM: AQUARIUM_ON|OFF|TOGGLE|STATUS.',
        camera: 'CAMERA: CAMERA_STATUS, CAMERA_HELP.',
        sms: 'SMS: SMS_STATUS, SMS_LOG.',
        energy: 'ENERGY: ENERGY_STATUS|START|STOP. HUAWEI_STATUS. SCALA1_STATUS|START|STOP.',
        consumer: 'CONSUMER: CONSUMER_STATUS. CONSUMER <id> ON|OFF (front|inside|outside|hut).'
    };
    if (domain && domainHelp[domain]) {
        return [replyParts(domainHelp[domain]), null];
    }
    if (domain) {
        return [replyParts('Unknown domain. Try HELP ENERGY, LIGHTS, ILLUM, IRRIG, GATE, SERVER, PUMP, CONSUMER.'), null];
    }
    return [replyParts('Domains: SERVER GATE GARDEN LIGHTS ILLUM IRRIG PUMP AQUARIUM CAMERA SMS ENERGY CONSUMER. Send HELP <domain>.'), null];
}

const dispatch = {
    from: to,
    command: cmd,
    args: args,
    originalText: msg.sms.originalText || ''
};
return [null, { payload: JSON.stringify(dispatch), topic: 'sms/command/dispatch' }];

let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString('utf8');
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) { return null; }
}
if (!payload) return null;

const items = Array.isArray(payload) ? payload : [payload];
const out = [];
for (const item of items) {
    if (!item || item.to == null || item.text == null) continue;
    const to = String(item.to).replace(/\D/g, '') || String(item.to);
    const text = String(item.text).substring(0, 150);
    if (!to || !text) continue;
    out.push({
        payload: JSON.stringify({ to: to, text: text }),
        topic: 'sms/gateway/command/send'
    });
}
return out.length ? [out] : null;
